// futari-nx (2026-10-19): Futari's own hooks of a Direct3D function Renut's renderer replaces hand over to it first
// thing (FUTARI_RENUT_YIELD(Name): Renut's entry, generated by tools/renut_futari_hooks.py), or call only the original
// while it is chosen (FUTARI_RENUT_ORIGINAL(sub_X): a function Renut leaves to the game, whose Futari hook belongs to
// another renderer). Nothing without FUTARI_RENUT_RENDERER.
#pragma once

#if FUTARI_RENUT_RENDERER
#include "renut_engine/gpu/banjo_renut_select.h"
#define FUTARI_RENUT_YIELD(name)                    \
  if (::banjo::renut_gpu::Active()) {               \
    futari_renut_entry_##name(ctx, base);           \
    return;                                         \
  }
#define FUTARI_RENUT_ORIGINAL(subroutine)           \
  if (::banjo::renut_gpu::Active()) {               \
    __imp__##subroutine(ctx, base);                 \
    return;                                         \
  }
#else
#define FUTARI_RENUT_YIELD(name)
#define FUTARI_RENUT_ORIGINAL(subroutine)
#endif
